// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    GasBurner burner;

    function setUp() public {
        c = new MyContract();
        burner = new GasBurner();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1, type(uint96).max);
        vm.deal(address(c), amount);

        bool ok;
        vm.prank(address(this));
        try c.sendTo(address(burner), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: any sendTo to a gas-hungry receiver must revert
        // (transfer grants only 2300 gas and propagates failure).
        assertTrue(!ok);
    }
}

contract GasBurner {
    uint256 public counter;
    receive() external payable {
        // SSTORE (~20k gas) far exceeds transfer's 2300-gas stipend.
        counter += 1;
    }
}
